export const galaxies=[{id:'origin',name:'The Familiar Unknown',center:[0,0,-60],color:'#7bb3ce',regions:['resonance','algebra','geometry','calculus','chance','networks']},{id:'aurelia',name:'Aurelia',center:[920,130,-800],color:'#eac681',regions:['aurelia']},{id:'umbra',name:'Umbra',center:[-860,-140,-900],color:'#bca6ed',regions:['umbra']}];
export function arrangeWorld(discoveries){const lookup=new Map(discoveries.map(d=>[d.id,d]));for(const [ri,region]of regions.entries()){let planet=0,asteroid=0,moon=0;region.members.forEach(([id,type],i)=>{const d=lookup.get(id);if(!d)throw Error('Unknown region member: '+id);d.region=region.id;d.kind=type;d.galaxy=galaxies.find(g=>g.regions.includes(region.id)).id;d.size={star:8,planet:5.6,moon:2.8,asteroid:2.3}[type];if(type==='moon'){d.parent=region.members.find(m=>m[1]==='planet')?.[0]||region.members[0][0];d.orbit={radius:17+moon++*8,phase:i*1.9,speed:.075,inclination:.42}}else if(type==='planet'){d.orbit={radius:57+planet++*30,phase:.55+ri*.38,speed:.012+ri*.001,inclination:.16+ri*.06}}else if(type==='asteroid'){d.orbit={radius:108+asteroid*18,phase:1.5+asteroid++*2.1,speed:.025+(i%3)*.007,inclination:.2+i*.13}}});}const positions=bodyPositions(discoveries,regions,0);for(const d of discoveries)d.pos=positions.get(d.id);return discoveries}
export function nearestRegion(position){return [...regions].sort((a,b)=>Math.hypot(...a.center.map((x,i)=>x-position[i]))-Math.hypot(...b.center.map((x,i)=>x-position[i])))[0]}
export const regionFor=id=>regions.find(r=>r.id===id);
